/**
 * Writes `fixtures/package/v15/comments.buildbox`, its `project.json` and its asset (#80 §1).
 *
 * Run it with `npx vite-node scripts/make-v15-package-fixture.ts`. The file is an ordinary production
 * Backup — the format this build writes — so any build can run the generator. Like every golden file
 * it is committed bytes, never regenerated by a test; `fixtures.test.ts` proves these bytes still
 * round-trip.
 *
 * The scene is the v14 one beside it, unchanged, with the one thing the fifteenth schema added
 * spelled out on the record the scene already carries: five Comments — a Project note, an entity
 * note, a Wall-face note with its parametric position, a cabinet space's note that has been resolved,
 * and a Floor Point note owned by one Design Option. It is the bytes the round-trip of a Project that
 * holds a Comment is judged against.
 */
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { canonicalJsonBytes } from '../src/lib'
import { encodeProject } from '../src/package/encode'
import { commentsFixtureProject, FIXTURE_BUILD, FIXTURE_PLAN_IMAGE_HASH } from '../src/package/testing'

const assetBytes = readFileSync(join('fixtures', 'package', 'v8', 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`))
const assetSource = async (): Promise<{ bytes: Uint8Array; mediaType: string }> => ({
  bytes: new Uint8Array(assetBytes),
  mediaType: 'image/png',
})

const project = commentsFixtureProject()
const bytes = await encodeProject(project, assetSource, FIXTURE_BUILD)

const dir = join('fixtures', 'package', 'v15')
mkdirSync(join(dir, 'assets'), { recursive: true })
writeFileSync(join(dir, 'comments.buildbox'), bytes)
writeFileSync(join(dir, 'project.json'), `${new TextDecoder().decode(canonicalJsonBytes(project))}\n`)
copyFileSync(join('fixtures', 'package', 'v8', 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`), join(dir, 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`))
console.info(`wrote ${join(dir, 'comments.buildbox')}: ${String(bytes.length)} bytes`)
